actor User {}
resource Repo {}

# Application provides repo.has_role(user_id, role).
has_role(user: User, role, repo: Repo) if repo.has_role(user.id, role);

# Allow read when the user is a viewer on the repo.
allow(user: User, "read", repo: Repo) if has_role(user, "viewer", repo);

actor User {}
resource Repo {}

# Application provides repo.has_role(user_id, role)
has_role(user: User, role: String, repo: Repo) if repo.has_role(user.id, role);

allow(user: User, "read", repo: Repo) if has_role(user, "viewer", repo);
allow(user: User, "write", repo: Repo) if has_role(user, "maintainer", repo);
allow(user: User, "admin", repo: Repo) if has_role(user, "admin", repo);

actor User { id: String }
resource Org { id: String }
resource Repo { id: String, org_id: String }

has_relation(u: User, "member", o: Org) if o.has_relation(u, "member");

allow(u: User, "read", r: Repo) if has_relation(u, "member", Org{id: r.org_id});
